package com.example.javaanalyzer.ir;

import java.util.List;

/**
 * A method or constructor.
 *
 * @param returnType null for constructors
 * @param comment non-Javadoc comment directly attached to the declaration, or null
 * @param bodyComments comments inside the body, in source order (kept as semantic hints for future
 *     use; empty for members without a body or generated by Lombok)
 * @param origin SOURCE, or LOMBOK when inferred from a Lombok annotation
 * @param generatedBy simple name of the Lombok annotation that generates this member (e.g. {@code
 *     Data}); null for source members
 */
public record MethodModel(
    String name,
    TypeRef returnType,
    List<ParameterModel> parameters,
    List<String> modifiers,
    List<AnnotationModel> annotations,
    String javadoc,
    String comment,
    List<String> bodyComments,
    MemberOrigin origin,
    String generatedBy) {

  public MethodModel {
    parameters = List.copyOf(parameters);
    modifiers = List.copyOf(modifiers);
    annotations = List.copyOf(annotations);
    bodyComments = List.copyOf(bodyComments);
  }
}
